<?php declare(strict_types=1); namespace App\People\Domain\Model; use App\People\Domain\Enum\FamilyRole; use App\People\Domain\ValueObject\FamilyId; use App\People\Domain\ValueObject\PersonId; use App\Shared\Domain\ValueObject\AuditTimestamps; final class Family {private array $members=[]; private function __construct(private readonly FamilyId $id,private string $name,private readonly AuditTimestamps $audit){} public static function create(FamilyId $id,string $name,\DateTimeImmutable $now):self{$name=trim($name);if($name==='')throw new \InvalidArgumentException('Family name cannot be empty.');return new self($id,$name,new AuditTimestamps($now,$now));} public static function reconstitute(FamilyId $id,string $name,AuditTimestamps $audit,array $members=[]):self{$f=new self($id,trim($name),$audit);foreach($members as $m)$f->members[$m->personId()->toString()]=$m;return $f;} public function id():FamilyId{return $this->id;} public function name():string{return $this->name;} public function createdAt():\DateTimeImmutable{return $this->audit->createdAt();} public function updatedAt():\DateTimeImmutable{return $this->audit->updatedAt();} public function rename(string $name,\DateTimeImmutable $now):void{$name=trim($name);if($name==='')throw new \InvalidArgumentException('Family name cannot be empty.');if($name!==$this->name){$this->name=$name;$this->audit->touch($now);}} public function addMember(PersonId $personId,FamilyRole $role,\DateTimeImmutable $now):void{$this->members[$personId->toString()]=FamilyMember::create($personId,$role,$now);$this->audit->touch($now);} public function removeMember(PersonId $personId,\DateTimeImmutable $now):void{if(isset($this->members[$personId->toString()])){unset($this->members[$personId->toString()]);$this->audit->touch($now);}} /** @return list<FamilyMember> */ public function members():array{return array_values($this->members);} }
